modules.moduleCss:
.hero-section {
  position: relative;
  min-height: 80vh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  padding: 80px 24px;
}

.hero-gradient {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: radial-gradient(ellipse at 30% 50%, rgba(232, 97, 58, 0.15) 0%, transparent 60%),
              radial-gradient(ellipse at 70% 50%, rgba(99, 102, 241, 0.1) 0%, transparent 60%);
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 1;
  text-align: center;
  max-width: 800px;
  margin: 0 auto;
}

.hero-heading {
  font-family: var(--font-heading);
  font-size: 4rem;
  font-weight: 800;
  color: var(--color-text);
  line-height: 1.1;
  margin: 0 0 24px;
  letter-spacing: -0.02em;
}

.hero-subheading {
  font-family: var(--font-body);
  font-size: 1.25rem;
  color: var(--color-text-muted);
  line-height: 1.7;
  margin: 0 0 40px;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.hero-cta-button {
  display: inline-block;
  padding: 16px 40px;
  background: var(--color-accent);
  color: #ffffff;
  font-family: var(--font-body);
  font-size: 1.1rem;
  font-weight: 600;
  text-decoration: none;
  border-radius: 8px;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.hero-cta-button:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 30px rgba(232, 97, 58, 0.35);
}

@media (max-width: 768px) {
  .hero-section {
    min-height: 60vh;
    padding: 60px 20px;
  }
  .hero-heading {
    font-size: 2.5rem;
  }
  .hero-subheading {
    font-size: 1.1rem;
  }
}

.features-section {
  padding: 100px 24px;
  background: var(--color-bg);
}

.features-container {
  max-width: 1200px;
  margin: 0 auto;
}

.features-title {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-text);
  text-align: center;
  margin: 0 0 60px;
  letter-spacing: -0.01em;
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.feature-card {
  background: var(--color-surface);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 12px;
  padding: 36px 28px;
  transition: border-color 0.2s ease, transform 0.2s ease;
}

.feature-card:hover {
  border-color: rgba(232, 97, 58, 0.3);
  transform: translateY(-4px);
}

.feature-icon {
  font-size: 2rem;
  display: block;
  margin-bottom: 16px;
}

.feature-card-title {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--color-text);
  margin: 0 0 12px;
}

.feature-card-description {
  font-family: var(--font-body);
  font-size: 1rem;
  color: var(--color-text-muted);
  line-height: 1.6;
  margin: 0;
}

@media (max-width: 768px) {
  .features-grid {
    grid-template-columns: 1fr;
    gap: 20px;
  }
  .features-title {
    font-size: 2rem;
  }
  .features-section {
    padding: 60px 20px;
  }
}

.pricing-section {
  padding: 100px 24px;
  background: var(--color-surface);
}

.pricing-container {
  max-width: 1200px;
  margin: 0 auto;
}

.pricing-title {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-text);
  text-align: center;
  margin: 0 0 60px;
  letter-spacing: -0.01em;
}

.pricing-grid {
  display: flex;
  gap: 28px;
  justify-content: center;
  align-items: stretch;
  flex-wrap: wrap;
}

.pricing-card {
  background: var(--color-bg);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 16px;
  padding: 40px 32px;
  flex: 1;
  min-width: 260px;
  max-width: 380px;
  display: flex;
  flex-direction: column;
  position: relative;
  transition: border-color 0.2s ease;
}

.pricing-card--featured {
  border-color: var(--color-accent);
  box-shadow: 0 0 40px rgba(232, 97, 58, 0.12);
}

.pricing-badge {
  position: absolute;
  top: -14px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-accent);
  color: #ffffff;
  font-family: var(--font-body);
  font-size: 0.8rem;
  font-weight: 600;
  padding: 6px 16px;
  border-radius: 20px;
  letter-spacing: 0.02em;
}

.pricing-tier-name {
  font-family: var(--font-heading);
  font-size: 1.3rem;
  font-weight: 600;
  color: var(--color-text);
  margin: 0 0 16px;
}

.pricing-price-wrap {
  margin-bottom: 28px;
}

.pricing-price {
  font-family: var(--font-heading);
  font-size: 3rem;
  font-weight: 800;
  color: var(--color-text);
  letter-spacing: -0.02em;
}

.pricing-period {
  font-family: var(--font-body);
  font-size: 1rem;
  color: var(--color-text-muted);
  margin-left: 4px;
}

.pricing-features-list {
  list-style: none;
  padding: 0;
  margin: 0 0 32px;
  flex-grow: 1;
}

.pricing-features-list li {
  font-family: var(--font-body);
  font-size: 0.95rem;
  color: var(--color-text-muted);
  padding: 8px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.04);
  line-height: 1.5;
}

.pricing-features-list li:last-child {
  border-bottom: none;
}

.pricing-button {
  display: block;
  text-align: center;
  padding: 14px 24px;
  font-family: var(--font-body);
  font-size: 1rem;
  font-weight: 600;
  text-decoration: none;
  border-radius: 8px;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  background: rgba(255, 255, 255, 0.08);
  color: var(--color-text);
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.pricing-button--featured {
  background: var(--color-accent);
  color: #ffffff;
  border-color: transparent;
}

.pricing-button:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.3);
}

@media (max-width: 768px) {
  .pricing-grid {
    flex-direction: column;
    align-items: center;
  }
  .pricing-card {
    max-width: 100%;
    min-width: auto;
    width: 100%;
  }
  .pricing-title {
    font-size: 2rem;
  }
  .pricing-section {
    padding: 60px 20px;
  }
}

.cta-section {
  padding: 100px 24px;
  position: relative;
  overflow: hidden;
}

.cta-container {
  max-width: 700px;
  margin: 0 auto;
  text-align: center;
  position: relative;
  z-index: 1;
}

.cta-heading {
  font-family: var(--font-heading);
  font-size: 2.8rem;
  font-weight: 800;
  color: #ffffff;
  margin: 0 0 20px;
  letter-spacing: -0.02em;
  line-height: 1.15;
}

.cta-description {
  font-family: var(--font-body);
  font-size: 1.15rem;
  color: rgba(255, 255, 255, 0.9);
  line-height: 1.7;
  margin: 0 0 40px;
}

.cta-button {
  display: inline-block;
  padding: 16px 40px;
  background: #ffffff;
  color: var(--color-accent);
  font-family: var(--font-body);
  font-size: 1.1rem;
  font-weight: 700;
  text-decoration: none;
  border-radius: 8px;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.cta-button:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.2);
}

@media (max-width: 768px) {
  .cta-section {
    padding: 60px 20px;
  }
  .cta-heading {
    font-size: 2rem;
  }
  .cta-description {
    font-size: 1rem;
  }
}

sharedCss:
:root {
  --color-bg: #0f0f23;
  --color-surface: #1a1a2e;
  --color-accent: #e8613a;
  --color-text: #ffffff;
  --color-text-muted: #a0a0b8;
  --font-heading: system-ui, -apple-system, sans-serif;
  --font-body: system-ui, -apple-system, sans-serif;
}

*, *::before, *::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 0;
  background: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-body);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

img {
  max-width: 100%;
  height: auto;
}

a {
  color: var(--color-accent);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}
